using namespace riscvdis;

// The rows: the code bytes in hex, the text, the setup and the expected state
struct RiscvSemanticRow {
    const char* m_code;
    const char* m_text;
    const char* m_setup;
    const char* m_expected;
};

#include "riscv/RiscvSemanticRows64.inc"
#include "riscv/RiscvSemanticRows32.inc"

static const RiscvSemanticRow gRiscv64SemanticRows[] = {
    RISCV64_SEMANTIC_ROWS
};

static const RiscvSemanticRow gRiscv32SemanticRows[] = {
    RISCV32_SEMANTIC_ROWS
};

// Report a failure and count it
#define RISCV_SEMANTIC_FAIL(row, message) \
    do { \
        fprintf(stderr, "TestRiscvSemantics: %s [%s]: %s\n", (row), \
                __FILE__, (message)); \
        m_failures++; \
    } while (0)

// A bad row of the tables is a failure of the test
#define RISCV_ASSERT_TOKEN(condition) \
    do { if (!(condition)) { fprintf(stderr, "bad row token\n"); TESTS_ASSERT(false); } } while (0)

// The memory of the rows (the memory of dismount_cli run): the data window
// is [0x80100000, + 0x4000) and holds the pattern
// ((uint32)(address * 2654435761) >> 24) unless the row sets bytes; the code
// region is the 3 pages around the page of the pc, zeros but the code; with
// the control flow integrity the shadow stack page 0x80200000 is a window
// too. The other addresses fault.
class TestRiscvRunMemory : public SemanticMemory {
public:
    TestRiscvRunMemory(const cBuffer& code, uint64 pc, bool isShadowStack) :
        m_code(code),
        m_pc(pc),
        m_isShadowStack(isShadowStack)
    {
    }

    virtual bool read(uint64 address, uint8* buffer, uint size)
    {
        for (uint i = 0; i < size; i++)
            if (!isMapped(address + i))
                return false;
        for (uint i = 0; i < size; i++)
            buffer[i] = getByte(address + i);
        return true;
    }

    virtual bool write(uint64 address, const uint8* buffer, uint size)
    {
        for (uint i = 0; i < size; i++)
            if (!isMapped(address + i))
                return false;
        for (uint i = 0; i < size; i++)
        {
            if (m_written.hasKey(address + i))
                m_written[address + i] = buffer[i];
            else
                m_written.append(address + i, buffer[i]);
        }
        return true;
    }

    // Set an initial byte (a mem= token of the setup)
    void setInitial(uint64 address, uint8 value)
    {
        if (m_initial.hasKey(address))
            m_initial[address] = value;
        else
            m_initial.append(address, value);
    }

    // The byte at the address now
    uint8 getByte(uint64 address) const
    {
        if (m_written.hasKey(address))
            return m_written[address];
        return getInitial(address);
    }

    // The byte at the address before the row ran
    uint8 getInitial(uint64 address) const
    {
        if ((address - m_pc) < m_code.getSize())
            return m_code[(uint)(address - m_pc)];
        if (m_initial.hasKey(address))
            return m_initial[address];
        if (isWindow(address))
            return (uint8)((uint32)(address * 2654435761u) >> 24);
        return 0;
    }

    cList<uint64> getWritten() const
    {
        return m_written.keys();
    }

    // Return true if the address is in the data window (not the code region)
    bool isWindow(uint64 address) const
    {
        return ((address - 0x80100000ULL) < 0x4000) ||
               (m_isShadowStack && ((address - 0x80200000ULL) < 0x1000));
    }

private:
    bool isMapped(uint64 address) const
    {
        const uint64 regionBase = (m_pc & ~(uint64)0xFFF) - 0x1000;
        return isWindow(address) || ((address - regionBase) < 0x3000);
    }

    cBuffer m_code;
    uint64 m_pc;
    bool m_isShadowStack;
    cHash<uint64, uint8> m_initial;
    cHash<uint64, uint8> m_written;
};

// Return the instruction which does not own the opcode
static OpcodePtr asOpcode(const RiscvOpcodePtr& opcode)
{
    return OpcodePtr((Opcode*)opcode.getPointer(), SMARTPTR_DESTRUCT_NONE);
}

class TestObjectTestRiscvSemantics : public cTestObject {
public:
    TestObjectTestRiscvSemantics() : m_failures(0) {}

private:
    // The value of a hexadecimal digit
    static uint digit(char c)
    {
        return (c >= 'a') ? (uint)(c - 'a' + 10) : (uint)(c - '0');
    }

    // Parse a hexadecimal number of up to 64 bits
    static uint64 parseHex(const char* text, const char* end)
    {
        uint64 value = 0;
        for (const char* p = text; p < end; p++)
            value = (value << 4) | digit(*p);
        return value;
    }

    // The tokens "name=value" of a string
    struct Token {
        char m_name[16];
        const char* m_value;
        const char* m_end;
    };

    enum { MAX_TOKENS = 96 };

    static uint split(const char* text, Token* tokens, uint maximum)
    {
        uint count = 0;
        const char* p = text;
        while ((*p != 0) && (count < maximum))
        {
            while (*p == ' ')
                p++;
            if (*p == 0)
                break;
            const char* end = p;
            while ((*end != 0) && (*end != ' '))
                end++;
            const char* equals = (const char*)memchr(p, '=', (size_t)(end - p));
            RISCV_ASSERT_TOKEN(equals != NULL);
            const uint length = (uint)(equals - p);
            RISCV_ASSERT_TOKEN(length < sizeof(tokens[count].m_name));
            memcpy(tokens[count].m_name, p, length);
            tokens[count].m_name[length] = 0;
            tokens[count].m_value = equals + 1;
            tokens[count].m_end = end;
            count++;
            p = end;
        }
        return count;
    }

    // Return the number after 'prefix' in a name ("x11" -> 11), or -1
    static int numbered(const char* name, char prefix)
    {
        if (name[0] != prefix)
            return -1;
        int value = 0;
        if (name[1] == 0)
            return -1;
        for (const char* p = name + 1; *p != 0; p++)
        {
            if ((*p < '0') || (*p > '9'))
                return -1;
            value = value * 10 + (*p - '0');
        }
        return (value < 32) ? value : -1;
    }

    // Parse "addr:hex,addr:hex" into the memory (the initial bytes) or into the
    // expected bytes
    static void parseMemory(const char* text, const char* end, TestRiscvRunMemory* memory,
                            cHash<uint64, uint8>* expected)
    {
        const char* p = text;
        while (p < end)
        {
            const char* colon = (const char*)memchr(p, ':', (size_t)(end - p));
            RISCV_ASSERT_TOKEN(colon != NULL);
            uint64 address = parseHex(p, colon);
            const char* q = colon + 1;
            uint count = 0;
            while ((q < end) && (*q != ','))
            {
                uint8 byte = (uint8)parseHex(q, q + 2);
                if (expected != NULL)
                {
                    if (expected->hasKey(address + count))
                        (*expected)[address + count] = byte;
                    else
                        expected->append(address + count, byte);
                } else
                {
                    memory->setInitial(address + count, byte);
                }
                q += 2;
                count++;
            }
            p = (q < end) ? q + 1 : q;
        }
    }

    // The state of a row
    struct State {
        State() : m_fcsr(0), m_ssp(0), m_elp(0), m_isCfi(false)
        {
            memset(m_x, 0, sizeof(m_x));
            memset(m_f, 0, sizeof(m_f));
        }

        uint64 m_x[32];
        uint64 m_f[32];
        uint64 m_fcsr;
        uint64 m_ssp;
        uint m_elp;
        bool m_isCfi;
    };

    // Run a row on RV64 or RV32. The row is OK if the state after the
    // instructions is the expected one: the registers which the row names have
    // the value, all the others are unchanged
    void runRow(const RiscvSemanticRow& row, bool is64)
    {
        const RiscvInstructionSet::DisassemblerTypes type = is64 ?
            RiscvInstructionSet::RISCV_RV64 : RiscvInstructionSet::RISCV_RV32;
        const OpcodeSubsystems::DisassemblerType subsystem =
                                    RiscvInstructionSet::toSubsystem(type);
        const uint64 addressMask = is64 ? ~(uint64)0 : 0xFFFFFFFFULL;
        const uint64 pc = 0x80001000ULL;

        // The code
        cBuffer code;
        {
            const uint digits = (uint)strlen(row.m_code);
            RISCV_ASSERT_TOKEN((digits % 2) == 0);
            code = cBuffer(digits / 2);
            for (uint i = 0; i < digits / 2; i++)
                code[i] = (uint8)((digit(row.m_code[2 * i]) << 4) |
                                  digit(row.m_code[2 * i + 1]));
        }

        // The start state
        Token tokens[MAX_TOKENS];
        State start;
        const uint setupCount = split(row.m_setup, tokens, MAX_TOKENS);
        for (uint i = 0; i < setupCount; i++)
        {
            const Token& t = tokens[i];
            if (strcmp(t.m_name, "fcsr") == 0)
                start.m_fcsr = parseHex(t.m_value, t.m_end);
            else if (strcmp(t.m_name, "ssp") == 0)
                start.m_ssp = parseHex(t.m_value, t.m_end);
            else if (strcmp(t.m_name, "elp") == 0)
                start.m_elp = (uint)parseHex(t.m_value, t.m_end) & 1;
            else if (strcmp(t.m_name, "cfi") == 0)
                start.m_isCfi = true;
            else if (strcmp(t.m_name, "mem") == 0)
                continue;
            else if (numbered(t.m_name, 'x') >= 0)
                start.m_x[numbered(t.m_name, 'x')] = parseHex(t.m_value, t.m_end) & addressMask;
            else if (numbered(t.m_name, 'f') >= 0)
                start.m_f[numbered(t.m_name, 'f')] = parseHex(t.m_value, t.m_end);
            else
                RISCV_ASSERT_TOKEN(false);
        }

        ArchitectureDescriptionPtr architecture(
                    new RiscvArchitecture(type, 128, start.m_isCfi));
        RiscvSemanticLifter lifter(subsystem, architecture);
        TestRiscvRunMemory memory(code, pc, start.m_isCfi);
        for (uint i = 0; i < setupCount; i++)
            if (strcmp(tokens[i].m_name, "mem") == 0)
                parseMemory(tokens[i].m_value, tokens[i].m_end, &memory, NULL);

        // Decode and lift
        SemanticBlock block(subsystem);
        uint offset = 0;
        while (offset < code.getSize())
        {
            const uint16 parcel = (uint16)(code[offset] | (code[offset + 1] << 8));
            const uint size = RiscvInstructionSet::getInstructionSize(parcel);
            uint32 encoding = parcel;
            if (size == 4)
                encoding |= ((uint32)code[offset + 2] << 16) |
                            ((uint32)code[offset + 3] << 24);
            RiscvOpcodePtr opcode = RiscvStreamDisassembler::decode(type, encoding,
                    size, (pc + offset) & addressMask, RiscvFeatureSet::all());
            if (opcode.getPointer() == NULL)
            {
                RISCV_SEMANTIC_FAIL(row.m_text, "the code doesn't decode");
                return;
            }
            if (!lifter.lift(asOpcode(opcode), block))
            {
                RISCV_SEMANTIC_FAIL(row.m_text, "the instruction isn't lifted");
                return;
            }
            offset += size;
        }
        block.setFallThroughAddress(ProcessorAddress(is64 ?
                ProcessorAddress::PROCESSOR_64 : ProcessorAddress::PROCESSOR_32,
                (pc + code.getSize()) & addressMask));

        SemanticInterpreter interpreter(architecture, memory);
        for (uint i = 1; i < 32; i++)
            interpreter.setRegister(RISCV_REG_X0 + i, SemanticValue(start.m_x[i]));
        interpreter.setRegister(RISCV_REG_PC, SemanticValue(pc));
        for (uint i = 0; i < 32; i++)
            interpreter.setRegister(RISCV_REG_F0 + i, SemanticValue(start.m_f[i]));
        interpreter.setRegister(RISCV_REG_FCSR, SemanticValue(start.m_fcsr));
        interpreter.setRegister(RISCV_REG_SSP, SemanticValue(start.m_ssp));
        interpreter.setRegister(RISCV_REG_ELP, SemanticValue(start.m_elp));
        SemanticInterpreter::ExitReason reason = interpreter.run(block);
        while (reason == SemanticInterpreter::EXIT_HELPER)
        {
            SemanticValue helperResult;
            if (!RiscvHelpers::execute(interpreter, is64 ? 64 : 32, helperResult))
                break;
            reason = interpreter.resume(helperResult);
        }

        // The expected state
        State wanted = start;
        bool hasX[32], hasF[32];
        bool hasPc = false, hasFcsr = false, hasSsp = false, hasElp = false;
        uint64 expectedPc = 0;
        cString exitName = "fall";
        cHash<uint64, uint8> expectedMemory;
        for (uint i = 0; i < 32; i++)
        {
            hasX[i] = false;
            hasF[i] = false;
        }
        const uint expectedCount = split(row.m_expected, tokens, MAX_TOKENS);
        for (uint i = 0; i < expectedCount; i++)
        {
            const Token& t = tokens[i];
            if (strcmp(t.m_name, "exit") == 0)
            {
                exitName = cString(cString(t.m_value).left((uint)(t.m_end - t.m_value)));
            } else if (strcmp(t.m_name, "mem") == 0)
            {
                parseMemory(t.m_value, t.m_end, NULL, &expectedMemory);
            } else if (strcmp(t.m_name, "pc") == 0)
            {
                hasPc = true;
                expectedPc = parseHex(t.m_value, t.m_end);
            } else if (strcmp(t.m_name, "fcsr") == 0)
            {
                hasFcsr = true;
                wanted.m_fcsr = parseHex(t.m_value, t.m_end);
            } else if (strcmp(t.m_name, "ssp") == 0)
            {
                hasSsp = true;
                wanted.m_ssp = parseHex(t.m_value, t.m_end);
            } else if (strcmp(t.m_name, "elp") == 0)
            {
                hasElp = true;
                wanted.m_elp = (uint)parseHex(t.m_value, t.m_end) & 1;
            } else if (numbered(t.m_name, 'x') >= 0)
            {
                hasX[numbered(t.m_name, 'x')] = true;
                wanted.m_x[numbered(t.m_name, 'x')] = parseHex(t.m_value, t.m_end);
            } else if (numbered(t.m_name, 'f') >= 0)
            {
                hasF[numbered(t.m_name, 'f')] = true;
                wanted.m_f[numbered(t.m_name, 'f')] = parseHex(t.m_value, t.m_end);
            } else
            {
                RISCV_ASSERT_TOKEN(false);
            }
        }

        // The exit
        cString actualExit;
        switch (reason)
        {
        case SemanticInterpreter::EXIT_FALL_THROUGH: actualExit = "fall"; break;
        case SemanticInterpreter::EXIT_BRANCH: actualExit = "branch"; break;
        case SemanticInterpreter::EXIT_MEMORY_FAULT: actualExit = "trap:fault"; break;
        case SemanticInterpreter::EXIT_HELPER: actualExit = "helper"; break;
        case SemanticInterpreter::EXIT_UNDEFINED: actualExit = "undefined"; break;
        case SemanticInterpreter::EXIT_TRAP:
            switch (interpreter.getTrapKind())
            {
            case SemanticOperation::TRAP_SYSTEM_CALL: actualExit = "trap:ecall"; break;
            case SemanticOperation::TRAP_BREAKPOINT: actualExit = "trap:ebreak"; break;
            case SemanticOperation::TRAP_UNDEFINED: actualExit = "trap:illegal"; break;
            default:
                actualExit = (interpreter.getTrapNumber() == RISCV_TRAP_SOFTWARE_CHECK) ?
                             "trap:swcheck" : "trap:fault";
                break;
            }
            break;
        default: actualExit = "other"; break;
        }
        // (a branch which lands on the next instruction is a fall through)
        if ((exitName == "fall") && (actualExit == "branch") &&
            (interpreter.getNextAddress() == ((pc + code.getSize()) & addressMask)))
            actualExit = "fall";
        if (!(actualExit == exitName))
        {
            char message[256];
            snprintf(message, sizeof(message), "exit %s, expected %s",
                     actualExit.getASCIIstring().getBuffer(),
                     exitName.getASCIIstring().getBuffer());
            RISCV_SEMANTIC_FAIL(row.m_text, message);
            return;
        }
        if (hasPc && (interpreter.getNextAddress() != expectedPc))
        {
            char message[256];
            snprintf(message, sizeof(message), "pc %llx, expected %llx",
                     (unsigned long long)interpreter.getNextAddress(),
                     (unsigned long long)expectedPc);
            RISCV_SEMANTIC_FAIL(row.m_text, message);
        }

        // The registers
        for (uint i = 1; i < 32; i++)
        {
            const uint64 actual = interpreter.getRegister(RISCV_REG_X0 + i).getWord(0);
            if (actual != wanted.m_x[i])
            {
                char message[256];
                snprintf(message, sizeof(message), "x%u = %llx, expected %llx", (unsigned int)i,
                         (unsigned long long)actual, (unsigned long long)wanted.m_x[i]);
                RISCV_SEMANTIC_FAIL(row.m_text, message);
            }
        }
        for (uint i = 0; i < 32; i++)
        {
            const uint64 actual = interpreter.getRegister(RISCV_REG_F0 + i).getWord(0);
            if (actual != wanted.m_f[i])
            {
                char message[256];
                snprintf(message, sizeof(message), "f%u = %llx, expected %llx", (unsigned int)i,
                         (unsigned long long)actual, (unsigned long long)wanted.m_f[i]);
                RISCV_SEMANTIC_FAIL(row.m_text, message);
            }
        }
        if ((interpreter.getRegister(RISCV_REG_FCSR).getWord(0) & 0xFF) !=
            (wanted.m_fcsr & 0xFF))
        {
            char message[256];
            snprintf(message, sizeof(message), "fcsr = %llx, expected %llx",
                     (unsigned long long)interpreter.getRegister(RISCV_REG_FCSR).getWord(0),
                     (unsigned long long)wanted.m_fcsr);
            RISCV_SEMANTIC_FAIL(row.m_text, message);
        }
        if (start.m_isCfi || hasSsp)
        {
            if (interpreter.getRegister(RISCV_REG_SSP).getWord(0) != wanted.m_ssp)
                RISCV_SEMANTIC_FAIL(row.m_text, "ssp");
        }
        if (interpreter.getRegister(RISCV_REG_ELP).getWord(0) != wanted.m_elp)
            RISCV_SEMANTIC_FAIL(row.m_text, "elp");
        (void)hasFcsr;
        (void)hasElp;

        // The memory: the expected bytes, and nothing else changed
        cList<uint64> keys = expectedMemory.keys();
        for (cList<uint64>::iterator i = keys.begin(); i != keys.end(); i++)
        {
            if (memory.getByte(*i) != expectedMemory[*i])
            {
                char message[256];
                snprintf(message, sizeof(message), "mem[%llx] = %02x, expected %02x",
                         (unsigned long long)*i, memory.getByte(*i), expectedMemory[*i]);
                RISCV_SEMANTIC_FAIL(row.m_text, message);
            }
        }
        cList<uint64> written = memory.getWritten();
        for (cList<uint64>::iterator i = written.begin(); i != written.end(); i++)
        {
            if (!expectedMemory.hasKey(*i) &&
                memory.isWindow(*i) &&
                (memory.getByte(*i) != memory.getInitial(*i)))
            {
                char message[256];
                snprintf(message, sizeof(message), "mem[%llx] was written", (unsigned long long)*i);
                RISCV_SEMANTIC_FAIL(row.m_text, message);
            }
        }
    }

    void testRows()
    {
        uint rows = 0;
        for (const RiscvSemanticRow* row = gRiscv64SemanticRows; row->m_text != NULL; row++)
        {
            runRow(*row, true);
            rows++;
        }
        for (const RiscvSemanticRow* row = gRiscv32SemanticRows; row->m_text != NULL; row++)
        {
            runRow(*row, false);
            rows++;
        }
        cout << rows << " RISC-V semantic rows run, " << m_failures << " failures" << endl;
        TESTS_ASSERT(m_failures == 0);
    }

    // Decode the 4 byte encoding for RV64 / RV32
    static RiscvOpcodePtr decodeWord(RiscvInstructionSet::DisassemblerTypes type,
                                     uint32 encoding, uint size)
    {
        return RiscvStreamDisassembler::decode(type, encoding, size, 0x80001000ULL,
                                               RiscvFeatureSet::all());
    }

    // Every mnemonic of the encoding tables the lifter decodes has an entry
    // in the semantic tables (but the vector ones, the aliases which are lifted by
    // the general encoding, and the entries only the assembler uses)
    void testCoverage()
    {
        uint missing = 0;
        const RiscvEncodingEntry* const tables[] = {
            gRiscvBaseEncodingTable, gRiscvPrivilegedEncodingTable
        };
        for (uint t = 0; t < sizeof(tables) / sizeof(tables[0]); t++)
        {
            for (const RiscvEncodingEntry* entry = tables[t]; entry->m_mnemonic != NULL; entry++)
            {
                if ((entry->m_flags & (RISCV_ENTRY_ASSEMBLE_ONLY | RISCV_ENTRY_ALIAS)) != 0)
                    continue;
                bool isFound = false;
                const RiscvSemanticEntry* semantic = (t == 0) ? gRiscvSemanticTable :
                                                     gRiscvPrivilegedSemanticTable;
                for (; semantic->m_template.m_name != NULL; semantic++)
                    if (strcmp(semantic->m_template.m_name, entry->m_mnemonic) == 0)
                        isFound = true;
                if (!isFound)
                {
                    fprintf(stderr, "TestRiscvSemantics: no semantic entry for %s\n", entry->m_mnemonic);
                    missing++;
                }
            }
        }
        // The aliases with a table entry of their own are lifted by it
        const char* const own[] = { "lpad", "pause", "fence.tso" };
        for (uint i = 0; i < sizeof(own) / sizeof(own[0]); i++)
        {
            bool isFound = false;
            for (const RiscvSemanticEntry* s = gRiscvSemanticTable; s->m_template.m_name != NULL; s++)
                if (strcmp(s->m_template.m_name, own[i]) == 0)
                    isFound = true;
            TESTS_ASSERT(isFound);
        }
        TESTS_ASSERT(missing == 0);
        // No mnemonic has two entries of the same operands count
        for (const RiscvSemanticEntry* a = gRiscvSemanticTable; a->m_template.m_name != NULL; a++)
            for (const RiscvSemanticEntry* b = a + 1; b->m_template.m_name != NULL; b++)
                if (strcmp(a->m_template.m_name, b->m_template.m_name) == 0)
                {
                    fprintf(stderr, "TestRiscvSemantics: %s is twice in the table\n", a->m_template.m_name);
                    TESTS_ASSERT(false);
                }
    }

    // The classification of the lifted mnemonics
    void testClassification()
    {
        RiscvSemanticLifter lifter(OpcodeSubsystems::DISASSEMBLER_RISCV_64);
        struct {
            uint32 m_word;
            OpcodeClassification::Category m_category;
            uint32 m_properties;
        } cases[] = {
            { 0x00c58533, OpcodeClassification::CATEGORY_ARITHMETIC, 0 },           // add a0, a1, a2
            { 0x0005a503, OpcodeClassification::CATEGORY_LOAD,
              OpcodeClassification::PROPERTY_READS_MEMORY },                        // lw a0, 0(a1)
            { 0x00a5a023, OpcodeClassification::CATEGORY_STORE,
              OpcodeClassification::PROPERTY_WRITES_MEMORY },                       // sw a0, 0(a1)
            { 0x00b50463, OpcodeClassification::CATEGORY_BRANCH,
              OpcodeClassification::PROPERTY_CONDITIONAL },                         // beq a0, a1, 8
            { 0x02c5c533, OpcodeClassification::CATEGORY_DIVIDE, 0 },               // div a0, a1, a2
            { 0x02c58533, OpcodeClassification::CATEGORY_MULTIPLY, 0 },             // mul a0, a1, a2
            { 0x10c5f553, OpcodeClassification::CATEGORY_FLOAT, 0 },                // fmul.s fa0, fa1, fa2
            { 0x1005a52f, OpcodeClassification::CATEGORY_ATOMIC,
              OpcodeClassification::PROPERTY_EXCLUSIVE },                           // lr.w a0, (a1)
            { 0x00000073, OpcodeClassification::CATEGORY_INTERRUPT, 0 },            // ecall
            { 0x60459513, OpcodeClassification::CATEGORY_BIT_MANIPULATION, 0 }      // sext.b a0, a1
        };
        for (uint i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
        {
            RiscvOpcodePtr opcode = decodeWord(RiscvInstructionSet::RISCV_RV64,
                                               cases[i].m_word, 4);
            TESTS_ASSERT(opcode.getPointer() != NULL);
            const OpcodeClassification c = lifter.classify(asOpcode(opcode));
            if (c.getCategory() != cases[i].m_category)
                cout << "FAILED classification of word " << HEXDWORD(cases[i].m_word) << endl;
            TESTS_ASSERT(c.getCategory() == cases[i].m_category);
            TESTS_ASSERT(c.hasProperty(cases[i].m_properties));
        }
        // A privileged instruction needs a helper and is privileged
        RiscvOpcodePtr mret = decodeWord(RiscvInstructionSet::RISCV_RV64, 0x30200073, 4);
        TESTS_ASSERT(mret.getPointer() != NULL);
        const OpcodeClassification m = lifter.classify(asOpcode(mret));
        TESTS_ASSERT(m.hasProperty(OpcodeClassification::PROPERTY_PRIVILEGED));
        TESTS_ASSERT(m.hasProperty(OpcodeClassification::PROPERTY_NEEDS_HELPER));
        // A compressed instruction is classified by its expansion
        RiscvOpcodePtr cadd = decodeWord(RiscvInstructionSet::RISCV_RV64, 0x9532, 2);   // c.add a0, a2
        TESTS_ASSERT(cadd.getPointer() != NULL);
        TESTS_ASSERT(lifter.classify(asOpcode(cadd)).getCategory() ==
                     OpcodeClassification::CATEGORY_ARITHMETIC);
        // A compressed hint does nothing
        RiscvOpcodePtr hint = decodeWord(RiscvInstructionSet::RISCV_RV64, 0x000d, 2);   // c.nop 3
        TESTS_ASSERT(hint.getPointer() != NULL);
        SemanticBlock block(OpcodeSubsystems::DISASSEMBLER_RISCV_64);
        TESTS_ASSERT(lifter.lift(asOpcode(hint), block));
        // The vector instructions are not lifted yet
        // (the table of the vector instructions is empty)
    }

    // The helper of the SM4 instructions and the counters
    void testHelpers()
    {
        TESTS_ASSERT(RiscvHelpers::getSm4Sbox(0x00) == 0xd6);
        TESTS_ASSERT(RiscvHelpers::getSm4Sbox(0x01) == 0x90);
        TESTS_ASSERT(RiscvHelpers::getSm4Sbox(0xff) == 0x48);
        TESTS_ASSERT(RiscvHelpers::getSm4Sbox(0x80) == 0xea);
    }

    virtual void test()
    {
        testCoverage();
        testRows();
        testClassification();
        testHelpers();
        cout << "RISC-V semantics tests passed" << endl;
    }

    // Return the name of the module
    virtual cString getName() { return __FILE__; }

private:
    uint m_failures;
};

// Instance test object
TestObjectTestRiscvSemantics g_globalTestRiscvSemantics;
